const $=q=>document.querySelector(q);let caseIndex=0,pathIndex=0,stepIndex=0,sampleKey='';let activeCatalogId=null,activeCatalogRoute=null;
function safeJson(value){return JSON.stringify(value,null,2)}
function getCase(){return cases[caseIndex]}function getPath(){return getCase().paths[pathIndex]}function getSample(){const c=getCase();return c.samples[sampleKey]||Object.values(c.samples)[0]}
function buildOutputs(path,sample){const outputs=[];path.steps.forEach((st,i)=>{let input=i===0?sample:(st.inputFrom!==undefined?outputs[st.inputFrom]:outputs[i-1]);if(st.inputMap)input=st.inputMap(outputs,sample);outputs.push(st.transform(input,sample,outputs))});return outputs}
function renderCases(){const el=$('#case-tabs');el.innerHTML=cases.map((c,i)=>`<button class="case-tab ${i===caseIndex?'active':''}" data-case="${i}"><span>${c.id}</span><b>${c.title}</b></button>`).join('')}
function renderPathTabs(){const c=getCase();$('#path-tabs').innerHTML=c.paths.map((p,i)=>`<button class="path-tab ${i===pathIndex?'active':''}" data-path="${i}">${p.label}</button>`).join('')}
function renderSampleOptions(){const select=$('#sample-select');if(!select)return;const options=Object.entries(getCase().samples).filter(([id,v])=>getPath().id==='live'?id==='event':!v.event_type);select.innerHTML=options.map(([id,v])=>`<option value="${id}">${v.name}</option>`).join('');select.value=options.some(([id])=>id===sampleKey)?sampleKey:options[0][0];sampleKey=select.value}
function renderRoute(){const p=getPath();$('#route-count').textContent=`${String(stepIndex+1).padStart(2,'0')} / ${String(p.steps.length).padStart(2,'0')}`;$('#route-list').innerHTML=p.steps.map((st,i)=>`<button class="route-step ${i===stepIndex?'active':''} ${i<stepIndex?'done':''}" data-step="${i}"><span class="number">${String(i+1).padStart(2,'0')}</span><span><b>${st.title}</b><small>${componentCatalog.find(c=>c.id===(st.componentId||st.id))?.service||st.component}</small></span><i>${i<stepIndex?'✓':'›'}</i></button>`).join('');$('#map-flow').innerHTML=p.steps.map((st,i)=>`${i?'<span class="map-arrow">→</span>':''}<span class="map-node ${i===stepIndex?'active':''} ${i<stepIndex?'done':''}">${st.kind.split(' / ')[0]}</span>`).join('');$('#trace-label').textContent=`${getCase().id} · ${p.label}`;$('#prev').disabled=stepIndex===0;$('#next').textContent=stepIndex===p.steps.length-1?'Reiniciar caso →':'Siguiente →'}
function renderDetail(){const p=getPath(),st=p.steps[stepIndex],data=getSample(),outputs=buildOutputs(p,data);let input=stepIndex===0?data:(st.inputFrom!==undefined?outputs[st.inputFrom]:outputs[stepIndex-1]);if(st.inputMap)input=st.inputMap(outputs,data);const output=outputs[stepIndex];const cat=componentCatalog.find(c=>c.id===(st.componentId||st.id));$('#step-kind').textContent=st.kind;$('#step-title').textContent=st.title;$('#step-purpose').textContent=st.purpose;$('#step-position').textContent=`PASO ${String(stepIndex+1).padStart(2,'0')} DE ${String(p.steps.length).padStart(2,'0')}`;$('#component-icon').textContent=(cat?.name||st.component).slice(0,1);$('#component-name').textContent=cat?`${cat.name} · ${cat.service}`:st.component;$('#stage-tag').textContent=cat?.status.split(' · ')[0]||'Simulación';$('#input-source').textContent=st.inputName||(stepIndex===0?'Fuente de datos':p.steps[st.inputFrom??stepIndex-1].title);$('#output-destination').textContent=st.outputName;$('#input-data').textContent=safeJson(input);$('#output-data').textContent=safeJson(output);$('#contract').textContent=st.contract;$('#contract-detail').textContent=cat?.status||'Contrato documentado en los activos del proyecto.';$('#validation').textContent=st.validation;$('#validation-detail').textContent='La simulación evalúa el ejemplo y representa la condición esperada.';$('#persistence').textContent=st.persistence;$('#persistence-detail').textContent=st.note||'Destino o mecanismo definido para esta etapa.';$('#step-explanation').textContent=st.note||st.purpose;const rel=[...(st.related||[]),...(controls[st.kind==='PUB/SUB'?'stream':'data']||[])].filter((id,i,a)=>a.indexOf(id)===i);$('#related-list').innerHTML=rel.map(id=>{const c=componentCatalog.find(x=>x.id===id);return c?`<button class="related-chip" data-component="${id}">${c.name}</button>`:''}).join('')}
function renderCase(){const c=getCase();$('#case-position').textContent=`${String(caseIndex+1).padStart(2,'0')} / 04`;$('#case-code').textContent=c.id;$('#case-title').textContent=c.title;$('#case-question').textContent=c.question;$('#case-product').textContent=c.product;$('#case-consumer').textContent=c.consumer;renderCases();renderPathTabs();renderSampleOptions();renderRoute();renderDetail()}
function findRouteForComponent(id){for(let ci=0;ci<cases.length;ci++)for(let pi=0;pi<cases[ci].paths.length;pi++){const path=cases[ci].paths[pi];for(let si=0;si<path.steps.length;si++)if((path.steps[si].componentId||path.steps[si].id)===id||(path.steps[si].related||[]).includes(id))return{ci,pi,si}}return null}
function renderCatalog(selected){const grid=$('#catalog-grid');grid.innerHTML=componentCatalog.map(c=>`<button class="catalog-item ${selected===c.id?'selected':''}" data-catalog="${c.id}"><b>${c.name}</b><small>${c.service}</small><em>${c.status.split(' · ')[0]}</em></button>`).join('');if(selected)showCatalogDetail(selected)}
function showCatalogDetail(id){const c=componentCatalog.find(x=>x.id===id);if(!c)return;activeCatalogId=id;activeCatalogRoute=findRouteForComponent(id);$('#catalog-name').textContent=c.name;$('#catalog-purpose').textContent=c.purpose;$('#catalog-input').textContent=c.in;$('#catalog-output').textContent=c.out;$('#catalog-contract').textContent=c.contract;$('#catalog-status').textContent=c.status;$('#catalog-go').hidden=!activeCatalogRoute;document.querySelectorAll('.catalog-item').forEach(b=>b.classList.toggle('selected',b.dataset.catalog===id))}
function openCatalog(id){renderCatalog(id||componentCatalog[0].id);$('#component-modal').classList.add('open');$('#component-modal').setAttribute('aria-hidden','false')}
function closeCatalog(){ $('#component-modal').classList.remove('open');$('#component-modal').setAttribute('aria-hidden','true')}
document.addEventListener('click',e=>{const caseBtn=e.target.closest('[data-case]');if(caseBtn){caseIndex=+caseBtn.dataset.case;pathIndex=0;stepIndex=0;sampleKey=Object.keys(getCase().samples)[0];renderCase();return}const pathBtn=e.target.closest('[data-path]');if(pathBtn){pathIndex=+pathBtn.dataset.path;stepIndex=0;renderCase();return}const stepBtn=e.target.closest('[data-step]');if(stepBtn){stepIndex=+stepBtn.dataset.step;renderRoute();renderDetail();return}const comp=e.target.closest('[data-component]');if(comp){openCatalog(comp.dataset.component);return}const cat=e.target.closest('[data-catalog]');if(cat){showCatalogDetail(cat.dataset.catalog);return}if(e.target.closest('#all-components')){openCatalog(activeCatalogId||'api');return}if(e.target.closest('[data-close]')){closeCatalog();return}if(e.target.closest('#catalog-go')&&activeCatalogRoute){caseIndex=activeCatalogRoute.ci;pathIndex=activeCatalogRoute.pi;stepIndex=activeCatalogRoute.si;closeCatalog();renderCase();return}if(e.target.closest('#prev')){if(stepIndex>0){stepIndex--;renderRoute();renderDetail()}return}if(e.target.closest('#next')){stepIndex=stepIndex===getPath().steps.length-1?0:stepIndex+1;renderRoute();renderDetail();return}});
$('#sample-select').addEventListener('change',e=>{sampleKey=e.target.value;renderRoute();renderDetail()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeCatalog();if(e.key==='ArrowLeft'&&stepIndex>0){stepIndex--;renderRoute();renderDetail()}if(e.key==='ArrowRight'&&stepIndex<getPath().steps.length-1){stepIndex++;renderRoute();renderDetail()}});
caseIndex=0;pathIndex=0;sampleKey=Object.keys(getCase().samples)[0];renderCase();
